// Input item (passthrough from the caller) is a bridge job spec:
//   { kind: 'claude', prompt, cwd, timeoutMin?, model?, retryModel?, requireStatusOk?, label? }
//   { kind: 'script', name, args, timeoutMin? }
// A claude spec may carry retryModel: if the first attempt fails, this sub-workflow runs ONE
// more attempt on that model (the failover/stronger model) with the failure appended as context.
const spec = $input.first().json;
if (spec.kind !== 'claude' && spec.kind !== 'script') {
  throw new Error(`job spec needs kind "claude" or "script", got ${JSON.stringify(spec.kind)}`);
}
const request = spec.kind === 'claude'
  ? { kind: 'claude', prompt: spec.prompt, cwd: spec.cwd, timeoutMin: spec.timeoutMin ?? 30, ...(spec.model ? { model: spec.model } : {}) }
  : { kind: 'script', name: spec.name, args: spec.args ?? [], timeoutMin: spec.timeoutMin ?? 10 };
return [{ json: { request } }];

// First attempt landed. Decide: succeeded (pass through), failed-but-retryable (emit a retry
// request), or failed-and-terminal (throw — the caller's error branch handles it).
const spec = $('When Called by Another Workflow').first().json;
const job = $input.first().json;
const label = spec.label || (spec.kind === 'script' ? spec.name : 'claude job');

function evalJob(j) {
  if (j.status !== 'succeeded') {
    const lines = String(j.logTail ?? '').split('\n').map((l) => l.trim()).filter(Boolean);
    const cause = j.error
      || [...lines].reverse().find((l) => /FATAL|error|fatal:|denied|not found/i.test(l))
      || lines.pop() || `job ended "${j.status}"`;
    return { ok: false, reason: (j.status === 'timeout' ? `timed out after ${spec.timeoutMin ?? '?'} min — ` : '') + cause };
  }
  if (spec.kind === 'claude') {
    const text = String(j.result ?? '');
    const lastLine = text.trim().split('\n').pop().replace(/[*`_]/g, '').trim();
    const blocked = lastLine.match(/^STATUS:\s*BLOCKED:?\s*(.*)$/);
    if (blocked) return { ok: false, reason: `Claude reported BLOCKED — ${blocked[1].trim() || 'no reason given'}` };
    if (spec.requireStatusOk && !/^STATUS:\s*OK$/.test(lastLine)) {
      return { ok: false, reason: 'Claude finished without a "STATUS: OK" line — treating as incomplete' };
    }
  }
  return { ok: true };
}

const v = evalJob(job);

if (v.ok) {
  return [{ json: {
    _retry: false,
    jobId: job.id, status: job.status, result: job.result, sessionId: job.sessionId,
    costUsd: job.costUsd, usage: job.usage ?? null, modelUsage: job.modelUsage ?? null,
    cwd: job.cwd, startedAt: job.createdAt, finishedAt: job.finishedAt,
    retried: false, models: [spec.model || '(default)'],
  } }];
}

// Failed. Retry only claude jobs that carry a retryModel; everything else is terminal.
if (spec.kind !== 'claude' || !spec.retryModel) {
  throw new Error(
    `${label}: ${v.reason}\n\nbridge job ${job.id} ended "${job.status}"` +
    (job.result ? `\n\nresult:\n${String(typeof job.result === 'string' ? job.result : JSON.stringify(job.result)).slice(-2000)}` : '') +
    (job.logTail ? `\n\nstderr tail:\n${job.logTail.slice(-2000)}` : '') +
    `\n\nfull logs: n8n/host-bridge/.jobs/${job.id}/`
  );
}

const failCtx = `\n\n---\nRETRY CONTEXT — a previous attempt using model ${spec.model || '(default)'} did not complete this phase:\n${v.reason}\nStart clean, diagnose the cause above, and finish the phase correctly.`;
return [{ json: {
  _retry: true,
  retryRequest: { kind: 'claude', prompt: String(spec.prompt) + failCtx, cwd: spec.cwd, timeoutMin: spec.timeoutMin ?? 30, model: spec.retryModel },
  attempt1: { jobId: job.id, costUsd: job.costUsd || 0, usage: job.usage || null, reason: v.reason },
} }];

// Retry (failover model) landed. Succeed with cost/tokens accumulated across BOTH attempts,
// or throw with the full two-attempt story for the caller's error branch.
const spec = $('When Called by Another Workflow').first().json;
const a1 = $('Assess Attempt').first().json.attempt1 || {};
const job = $input.first().json;
const label = spec.label || 'claude job';

function evalJob(j) {
  if (j.status !== 'succeeded') {
    const lines = String(j.logTail ?? '').split('\n').map((l) => l.trim()).filter(Boolean);
    const cause = j.error
      || [...lines].reverse().find((l) => /FATAL|error|fatal:|denied|not found/i.test(l))
      || lines.pop() || `job ended "${j.status}"`;
    return { ok: false, reason: (j.status === 'timeout' ? `timed out after ${spec.timeoutMin ?? '?'} min — ` : '') + cause };
  }
  const text = String(j.result ?? '');
  const lastLine = text.trim().split('\n').pop().replace(/[*`_]/g, '').trim();
  const blocked = lastLine.match(/^STATUS:\s*BLOCKED:?\s*(.*)$/);
  if (blocked) return { ok: false, reason: `Claude reported BLOCKED — ${blocked[1].trim() || 'no reason given'}` };
  if (spec.requireStatusOk && !/^STATUS:\s*OK$/.test(lastLine)) {
    return { ok: false, reason: 'Claude finished without a "STATUS: OK" line — treating as incomplete' };
  }
  return { ok: true };
}

function mergeUsage(x, y) {
  if (!x && !y) return null;
  const o = { ...(x || {}) };
  for (const [k, val] of Object.entries(y || {})) if (typeof val === 'number') o[k] = (o[k] || 0) + val;
  return o;
}

const v = evalJob(job);
const costUsd = Math.round(((a1.costUsd || 0) + (job.costUsd || 0)) * 100) / 100;
const usage = mergeUsage(a1.usage, job.usage);

if (!v.ok) {
  throw new Error(
    `${label}: retry on ${spec.retryModel} also failed — ${v.reason}\n\n` +
    `(first attempt on ${spec.model || '(default)'}: ${a1.reason || '?'})\n\nbridge job ${job.id} ended "${job.status}"` +
    (job.result ? `\n\nresult:\n${String(typeof job.result === 'string' ? job.result : JSON.stringify(job.result)).slice(-2000)}` : '') +
    (job.logTail ? `\n\nstderr tail:\n${job.logTail.slice(-2000)}` : '') +
    `\n\nfull logs: n8n/host-bridge/.jobs/${job.id}/`
  );
}

return [{ json: {
  jobId: job.id, status: job.status, result: job.result, sessionId: job.sessionId,
  costUsd, usage, modelUsage: job.modelUsage ?? null,
  cwd: job.cwd, startedAt: job.createdAt, finishedAt: job.finishedAt,
  retried: true, models: [spec.model || '(default)', spec.retryModel],
} }];
